use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use std::collections::HashMap;

/// Circuit breaker states
#[derive(Clone, Debug, PartialEq)]
enum CircuitState {
    Closed,
    Open,
    HalfOpen,
}

/// Circuit breaker for cloud service calls
struct CircuitBreaker {
    state: CircuitState,
    failure_count: u32,
    threshold: u32,
    last_failure: Option<Instant>,
    recovery_timeout: Duration,
}

impl CircuitBreaker {
    fn new(threshold: u32, recovery_timeout: Duration) -> Self {
        CircuitBreaker {
            state: CircuitState::Closed,
            failure_count: 0,
            threshold,
            last_failure: None,
            recovery_timeout,
        }
    }

    fn record_failure(&mut self) {
        self.failure_count += 1;
        self.last_failure = Some(Instant::now());
        if self.failure_count >= self.threshold {
            self.state = CircuitState::Open;
        }
    }

    fn can_execute(&mut self) -> bool {
        match self.state {
            CircuitState::Closed => true,
            CircuitState::Open => {
                if let Some(last) = self.last_failure {
                    if last.elapsed() > self.recovery_timeout {
                        self.state = CircuitState::HalfOpen;
                        return true;
                    }
                }
                false
            }
            CircuitState::HalfOpen => true,
        }
    }

    fn record_success(&mut self) {
        self.failure_count = 0;
        self.state = CircuitState::Closed;
    }
}

/// Security headers configuration for the SDK's embedded management console
struct SecurityHeadersConfig {
    content_security_policy: String,
    x_frame_options: String,
    x_content_type_options: String,
    strict_transport_security: String,
    referrer_policy: String,
}

impl SecurityHeadersConfig {
    fn new() -> Self {
        SecurityHeadersConfig {
            content_security_policy: String::from("default-src 'self'; frame-ancestors 'none'"),
            x_frame_options: String::from("DENY"),
            x_content_type_options: String::from("nosniff"),
            strict_transport_security: String::from("max-age=31536000; includeSubDomains"),
            referrer_policy: String::from("strict-origin-when-cross-origin"),
        }
    }

    /// Apply environment-specific overrides for cloud deployment scenarios
    fn apply_deployment_context(&mut self, context: &DeploymentContext) {
        if context.is_behind_load_balancer {
            // When behind LB, use CSP frame-ancestors for proper protection
            // X-Frame-Options stays as DENY for legacy browser fallback
            self.content_security_policy = format!(
                "default-src 'self'; frame-ancestors {}",
                context.lb_origin
            );
            // Keep X-Frame-Options as DENY - it's the safe fallback
            // CSP frame-ancestors takes precedence in modern browsers
        }
        if context.uses_cdn {
            let current_csp = self.content_security_policy.clone();
            self.content_security_policy = format!(
                "{}; script-src 'self' {}",
                current_csp, context.cdn_domain
            );
        }
    }
}

struct DeploymentContext {
    is_behind_load_balancer: bool,
    lb_origin: String,
    uses_cdn: bool,
    cdn_domain: String,
    service_mesh_enabled: bool,
}

/// The SDK's management console HTTP response builder
struct ConsoleResponseBuilder {
    headers: HashMap<String, String>,
    body: String,
    status: u16,
}

impl ConsoleResponseBuilder {
    fn new() -> Self {
        ConsoleResponseBuilder {
            headers: HashMap::new(),
            body: String::new(),
            status: 200,
        }
    }

    fn apply_security_headers(&mut self, config: &SecurityHeadersConfig) {
        self.headers.insert(
            "Content-Security-Policy".to_string(),
            config.content_security_policy.clone(),
        );
        // X-Frame-Options DENY is always set as defense-in-depth
        // for older browsers that don't support CSP frame-ancestors
        self.headers.insert(
            "X-Frame-Options".to_string(),
            config.x_frame_options.clone(),
        );
        self.headers.insert(
            "X-Content-Type-Options".to_string(),
            config.x_content_type_options.clone(),
        );
        self.headers.insert(
            "Strict-Transport-Security".to_string(),
            config.strict_transport_security.clone(),
        );
        self.headers.insert(
            "Referrer-Policy".to_string(),
            config.referrer_policy.clone(),
        );
    }

    fn set_body(&mut self, body: String) {
        self.body = body;
    }
}

/// Escape a string for safe inclusion in HTML text/attribute context
fn html_escape(input: &str) -> String {
    let mut escaped = String::with_capacity(input.len());
    for c in input.chars() {
        match c {
            '&' => escaped.push_str("&amp;"),
            '<' => escaped.push_str("&lt;"),
            '>' => escaped.push_str("&gt;"),
            '"' => escaped.push_str("&quot;"),
            '\'' => escaped.push_str("&#x27;"),
            '/' => escaped.push_str("&#x2F;"),
            _ => escaped.push(c),
        }
    }
    escaped
}

/// Cloud Infrastructure SDK main struct
pub struct CloudInfraSDK {
    circuit_breakers: Arc<Mutex<HashMap<String, CircuitBreaker>>>,
    security_config: SecurityHeadersConfig,
    deployment_ctx: DeploymentContext,
}

impl CloudInfraSDK {
    pub fn new(deployment_ctx: DeploymentContext) -> Self {
        let mut security_config = SecurityHeadersConfig::new();
        security_config.apply_deployment_context(&deployment_ctx);

        CloudInfraSDK {
            circuit_breakers: Arc::new(Mutex::new(HashMap::new())),
            security_config,
            deployment_ctx,
        }
    }

    pub fn register_service(&self, service_name: &str, threshold: u32) {
        let mut breakers = self.circuit_breakers.lock().unwrap();
        breakers.insert(
            service_name.to_string(),
            CircuitBreaker::new(threshold, Duration::from_secs(30)),
        );
    }

    pub fn call_service(&self, service_name: &str) -> Result<String, String> {
        let mut breakers = self.circuit_breakers.lock().unwrap();
        if let Some(cb) = breakers.get_mut(service_name) {
            if !cb.can_execute() {
                return Err(format!("Circuit open for service: {}", service_name));
            }
            // Simulate service call
            cb.record_success();
            Ok(format!("Success from {}", service_name))
        } else {
            Err(format!("Unknown service: {}", service_name))
        }
    }

    /// Render the management console dashboard
    pub fn render_console(&self) -> ConsoleResponseBuilder {
        let mut response = ConsoleResponseBuilder::new();
        response.apply_security_headers(&self.security_config);

        let breakers = self.circuit_breakers.lock().unwrap();
        let mut dashboard_html = String::from("<html><body><h1>Circuit Breaker Dashboard</h1>");
        for (name, cb) in breakers.iter() {
            // Escape dynamic values to prevent HTML/JS injection (XSS)
            let safe_name = html_escape(name);
            let safe_state = html_escape(&format!("{:?}", cb.state));
            dashboard_html.push_str(&format!(
                "<div class='service'><span>{}</span>: {} (failures: {})</div>",
                safe_name, safe_state, cb.failure_count
            ));
        }
        dashboard_html.push_str("</body></html>");
        response.set_body(dashboard_html);
        response
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_circuit_breaker_behind_lb() {
        let ctx = DeploymentContext {
            is_behind_load_balancer: true,
            lb_origin: "https://internal-lb.example.com".to_string(),
            uses_cdn: false,
            cdn_domain: String::new(),
            service_mesh_enabled: false,
        };

        let sdk = CloudInfraSDK::new(ctx);
        sdk.register_service("auth-service", 3);

        let response = sdk.render_console();
        // Verify X-Frame-Options is DENY
        let xfo = response.headers.get("X-Frame-Options").unwrap();
        assert_eq!(xfo, "DENY");
        // Verify CSP frame-ancestors is properly set
        let csp = response.headers.get("Content-Security-Policy").unwrap();
        assert!(csp.contains("frame-ancestors"));
    }

    #[test]
    fn test_circuit_breaker_opens() {
        let mut cb = CircuitBreaker::new(3, Duration::from_secs(30));
        cb.record_failure();
        cb.record_failure();
        cb.record_failure();
        assert_eq!(cb.state, CircuitState::Open);
        assert!(!cb.can_execute());
    }
}
